import React, { useState, useEffect, useRef } from 'react';

const VoiceWeb = ({ onNavigate }) => {
    // 1. STATE MANAGEMENT
    const [step, setStep] = useState('language'); 
    const [transcript, setTranscript] = useState([]);
    const [isListening, setIsListening] = useState(false);
    const [engineStatus, setEngineStatus] = useState({ status: 'IDLE', step: 'START', mic: 'LOCKED' });

    // THE 4 DEMO PNRS
    const VALID_PNRS = ["SKY789", "SYNC456", "TRK123", "FLY999"];

    const scrollRef = useRef(null);

    // 2. NATIVE LANGUAGE DATA
    const languages = [
        { name: 'English', native: 'English' },
        { name: 'Telugu', native: 'తెలుగు' },
        { name: 'Hindi', native: 'हिन्दी' },
        { name: 'Tamil', native: 'தமிழ்' },
        { name: 'Kannada', native: 'ಕನ್ನಡ' }, // Corrected to Kannada Script
        { name: 'Malayalam', native: 'മലയാളം' },
        { name: 'Bengali', native: 'বাংলা' },
        { name: 'Marathi', native: 'मराठी' }, // Corrected to Devanagari Script
        { name: 'Gujarati', native: 'ગુજરાતી' },
        { name: 'Punjabi', native: 'ਪੰਜਾਬੀ' }
    ];

    const services = [
        "Flight Booking", "Live Status", "Web Check-in", "Baggage Claim", 
        "Meal Request", "Seat Upgrade", "Refund Status", "Support", 
        "Cancel Trip", "Group Booking"
    ];

    // 3. VOICE ENGINE LOGIC
    const speak = (text) => {
        const utternace = new SpeechSynthesisUtterance(text);
        window.speechSynthesis.speak(utternace);
        // Add AI message to left side of chat
        setTranscript(prev => [...prev, { sender: 'ai', text: text }]);
    };

    const startListening = () => {
        setIsListening(true);
        setEngineStatus(prev => ({ ...prev, mic: 'ACTIVE', status: 'LISTENING' }));

        // Simulating Voice Input for Demo
        setTimeout(() => {
            handleVoiceInput("Simulated User Voice Input");
        }, 3000);
    };

    const handleVoiceInput = (userInput) => {
        setIsListening(false);
        setEngineStatus(prev => ({ ...prev, mic: 'LOCKED', status: 'PROCESSING' }));

        // Add User message to right side of chat
        setTranscript(prev => [...prev, { sender: 'user', text: userInput }]);

        // Logic Switch based on conversation step
        setTimeout(() => {
            if (step === 'language') {
                setStep('service');
                speak("Language confirmed. Please select your service from the list on the right.");
            } else if (step === 'service') {
                setStep('cities');
                speak("Great. Please state your departure and destination cities.");
            } else if (step === 'cities') {
                setStep('preferences');
                speak("Flights found. Would you like Business or Economy class? And do you have extra baggage?");
            } else if (step === 'preferences') {
                const finalPnr = VALID_PNRS[Math.floor(Math.random() * VALID_PNRS.length)];
                speak(`Booking Successful! Your PNR is ${finalPnr}. Your tracking ID has been generated. You can now track this in the main dashboard.`);
                setEngineStatus({ status: 'COMPLETED', step: 'SUCCESS', mic: 'LOCKED' });
            }
        }, 1500);
    };

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [transcript]);

    return (
        <div style={{ background: '#070b14', height: '100vh', display: 'flex', flexDirection: 'column', color: '#e2e8f0', fontFamily: 'serif' }}>

            {/* HEADER */}
            <div style={{ padding: '15px 25px', borderBottom: '1px solid #1e293b', display: 'flex', alignItems: 'center', gap: '20px' }}>
                <button onClick={() => onNavigate('dashboard')} style={{ background: 'none', border: 'none', color: '#3b82f6', cursor: 'pointer', fontSize: '20px' }}>←</button>
                <h2 style={{ fontSize: '18px', letterSpacing: '2px', margin: 0 }}>SKY-SYNC AI</h2>
            </div>

            <div style={{ flex: 1, display: 'flex', overflow: 'hidden' }}>

                {/* LEFT: LANGUAGES */}
                <div style={{ width: '250px', borderRight: '1px solid #1e293b', padding: '20px', overflowY: 'auto' }}>
                    <p style={{ fontSize: '10px', color: '#60a5fa', marginBottom: '15px' }}>LANGUAGES</p>
                    {languages.map(lang => (
                        <div key={lang.name} style={{ background: '#111827', padding: '12px', borderRadius: '8px', marginBottom: '8px', border: '1px solid #1e293b', fontSize: '12px', display: 'flex', justifyContent: 'space-between' }}>
                            <span>{lang.name}</span>
                            <span style={{ opacity: 0.5 }}>({lang.native})</span>
                        </div>
                    ))}
                </div>

                {/* CENTER: CHAT ENGINE (LIVE TRANSCRIPTS) */}
                <div style={{ flex: 1, display: 'flex', flexDirection: 'column', background: '#0a0f1d', position: 'relative' }}>

                    {/* TRANSCRIPT AREA */}
                    <div ref={scrollRef} style={{ flex: 1, padding: '30px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '15px' }}>
                        {transcript.length === 0 && (
                            <div style={{ textAlign: 'center', marginTop: '20%', opacity: 0.3 }}>
                                <p>Voice Web Engine Standby...</p>
                                <p style={{ fontSize: '12px' }}>Click the microphone to begin booking</p>
                            </div>
                        )}
                        {transcript.map((msg, i) => (
                            <div key={i} style={{ 
                                alignSelf: msg.sender === 'ai' ? 'flex-start' : 'flex-end',
                                maxWidth: '70%',
                                background: msg.sender === 'ai' ? '#1e293b' : '#2563eb',
                                padding: '12px 18px',
                                borderRadius: msg.sender === 'ai' ? '0 15px 15px 15px' : '15px 15px 0 15px',
                                fontSize: '14px',
                                boxShadow: '0 4px 6px rgba(0,0,0,0.1)'
                            }}>
                                {msg.text}
                            </div>
                        ))}
                    </div>

                    {/* MIC CONTROL */}
                    <div style={{ height: '120px', borderTop: '1px solid #1e293b', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#070b14' }}>
                        <button 
                            onClick={startListening}
                            style={{ 
                                width: '60px', height: '60px', borderRadius: '50%', 
                                border: 'none', background: isListening ? '#ef4444' : '#3b82f6', 
                                cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center',
                                boxShadow: isListening ? '0 0 20px #ef4444' : 'none',
                                transition: '0.3s'
                            }}
                        >
                            <span style={{ fontSize: '24px' }}>{isListening ? '⏹' : '🎤'}</span>
                        </button>
                    </div>
                </div>

                {/* RIGHT: SERVICES & STATUS */}
                <div style={{ width: '300px', borderLeft: '1px solid #1e293b', padding: '20px', display: 'flex', flexDirection: 'column' }}>
                    <p style={{ fontSize: '10px', color: '#60a5fa', marginBottom: '15px' }}>SERVICES</p>
                    <div style={{ flex: 1, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '8px', marginBottom: '20px' }}>
                        {services.map(service => (
                            <div key={service} style={{ background: '#111827', padding: '10px', borderRadius: '8px', border: '1px solid #1e293b', fontSize: '11px' }}>
                                {service}
                            </div>
                        ))}
                    </div>

                    {/* ENGINE STATUS AREA */}
                    <div style={{ background: '#0f172a', padding: '15px', borderRadius: '12px', border: '1px solid #3b82f6' }}>
                        <p style={{ fontSize: '10px', color: '#3b82f6', margin: '0 0 10px 0', fontWeight: 'bold' }}>ENGINE STATUS</p>
                        <div style={{ fontSize: '11px', fontFamily: 'monospace', display: 'flex', flexDirection: 'column', gap: '4px' }}>
                            <div>STATUS: <span style={{ color: '#22c55e' }}>{engineStatus.status}</span></div>
                            <div>STEP: {step.toUpperCase()}</div>
                            <div>MIC: <span style={{ color: isListening ? '#ef4444' : '#64748b' }}>{engineStatus.mic}</span></div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default VoiceWeb;
